command:
$ErrorActionPreference = "Stop"
git fetch origin main work/search-v3-criteria --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "433e26a5278af97be4c58edc362549d52abf778a") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }

$evidence="C:\dev\flyExplorer\logs\remote-evidence"
if (Test-Path $evidence) { Remove-Item -Recurse -Force $evidence }
New-Item -ItemType Directory -Force -Path $evidence | Out-Null

git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "main fast-forward failed" }

$productDrift=@(git diff --name-only a7490083000ac8faeb6c4fbe2cf54fecd6b00cf8..HEAD -- app/winui src/base)
if ($productDrift.Count -ne 0) { throw "main product source drifted from validated Release binary" }
if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "validated main Release binary missing" }

$env:FLY_MIGRATION_CONFIGURATION="Release"
$env:FLY_M19_OWNED_FEATURES="YES"
python -X utf8 tests\winui\test_shell_gui.py
if ($LASTEXITCODE -ne 0) { throw "main baseline M1.9 GUI failed" }
Copy-Item "logs\phase6-winui\migration-first-shell-real-gui.png" (Join-Path $evidence "search-v3-before.png")

git checkout work/search-v3-criteria
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/search-v3-criteria
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

Write-Host "M19_NATIVE_RELEASE"
cmd /c tests\winui\m19\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M19 Release build failed" }
cmd /c "set FLY_M19_CONFIG=Release&& python -X utf8 tests\winui\m19\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M19 native fixture failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "OWNED_M19_GUI"
$env:FLY_MIGRATION_CONFIGURATION="Release"
$env:FLY_M19_OWNED_FEATURES="YES"
python -X utf8 tests\winui\test_shell_gui.py
if ($LASTEXITCODE -ne 0) { throw "Search v3 owned GUI failed" }
Copy-Item "logs\phase6-winui\migration-first-shell-real-gui.png" (Join-Path $evidence "search-v3-after.png")

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

@"
feature=search-v3-criteria
main=433e26a5278af97be4c58edc362549d52abf778a
candidate=13e4f1fd2b647ba4d9f24d2b7c19fa296cf2047b
"@ | Set-Content -Encoding UTF8 (Join-Path $evidence "manifest.txt")

Write-Host "SEARCH_V3_PREMAIN_PASS"
